// Pure path rules: canonical form, legacy URL redirects and language prefixes (Req 23.1, design "Languages").

export type Lang = 'en' | 'hi';

/** Legacy_Storefront page paths that moved. Query strings are kept by the router. */
const LEGACY_EXACT: Record<string, string> = {
  '/home': '/',
  '/index.html': '/',
  '/index': '/',
};
const LEGACY_PREFIX: Array<[from: string, to: string]> = [
  ['/products/', '/product/'],
  ['/collection/', '/collections/'],
];

/** Canonical path: single slashes, lower case, no trailing slash, no `/en` prefix, legacy paths mapped. */
export function canonicalPath(pathname: string): string {
  let p = pathname.replace(/\/{2,}/g, '/').toLowerCase();
  if (!p.startsWith('/')) p = `/${p}`;
  if (p.length > 1 && p.endsWith('/')) p = p.replace(/\/+$/, '') || '/';
  if (p === '/en') p = '/';
  else if (p.startsWith('/en/')) p = p.slice(3);
  if (p === '/hi/') p = '/hi';
  const exact = LEGACY_EXACT[p];
  if (exact !== undefined) return exact;
  for (const [from, to] of LEGACY_PREFIX) {
    if (p.startsWith(from)) return `${to}${p.slice(from.length)}`;
  }
  if (p === '/hi/index.html' || p === '/hi/home') return '/hi';
  return p;
}

/** Language of a canonical path and the path without the `/hi` prefix. */
export function splitLang(path: string): { lang: Lang; path: string } {
  if (path === '/hi') return { lang: 'hi', path: '/' };
  if (path.startsWith('/hi/')) return { lang: 'hi', path: path.slice(3) };
  return { lang: 'en', path };
}

export type Route =
  | { kind: 'live' }
  | { kind: 'preview'; lang: Lang; path: string }
  | { kind: 'catalog'; lang: Lang; path: string }
  | { kind: 'notFound' };

const CATALOG = /^\/(product|collections)\/[^/]+$|^\/shop(\/[^/]+)+$/;

/** Route of a canonical path (the table of design "Storefront_Worker and Live_Data"). */
export function routeOf(path: string): Route {
  if (path === '/_live/v1/products') return { kind: 'live' };
  if (path.startsWith('/_preview/')) {
    const { lang, path: rest } = splitLang(path.slice('/_preview'.length));
    return { kind: 'preview', lang, path: rest };
  }
  const { lang, path: rest } = splitLang(path);
  if (CATALOG.test(rest)) return { kind: 'catalog', lang, path: rest };
  return { kind: 'notFound' };
}
