// Small client for spec 1's `api.store_resolve_path(p_record_type, p_handle, p_v)` (design KD-5), the Worker's
// outgoing call for catalog paths: GET /rest/v1/rpc/store_resolve_path?p_record_type=..&p_handle=.. with
// `Accept-Profile: api`. It answers {result: found | redirect | not_found, http_status, id, handle, path}, where
// `path` of a category is the root-to-record handle list (the URL is /shop/<path joined with />).
import { originOf } from '../../scripts/security-headers.mjs';
import type { WorkerEnv } from './env';
import { splitLang } from './paths';

export type ResolveResult =
  | { kind: 'published' }
  | { kind: 'redirect'; path: string }
  | { kind: 'none' };

export class ResolveError extends Error {}

export type Fetcher = (input: string, init?: RequestInit) => Promise<Response>;

/** Fetch that refuses every origin other than the Supabase project (Req 21.7). */
export function guardedFetch(supabaseUrl: string, inner: Fetcher = (u, i) => fetch(u, i)): Fetcher {
  const allowed = originOf(supabaseUrl);
  return (input, init) => {
    if (!allowed || originOf(input) !== allowed) {
      return Promise.reject(new ResolveError(`Outgoing request to ${input} is not allowed`));
    }
    return inner(input, init);
  };
}

export type RecordType = 'product' | 'category' | 'collection';

/** Record type and handle of a canonical path without language prefix; null for a path that is no record. */
export function recordOf(path: string): { type: RecordType; handle: string; segments: string[] } | null {
  const parts = path.split('/').filter(Boolean);
  const last = parts[parts.length - 1];
  if (!last) return null;
  if (parts.length === 2 && parts[0] === 'product') return { type: 'product', handle: last, segments: parts.slice(1) };
  if (parts.length === 2 && parts[0] === 'collections') return { type: 'collection', handle: last, segments: parts.slice(1) };
  if (parts.length >= 2 && parts[0] === 'shop') return { type: 'category', handle: last, segments: parts.slice(1) };
  return null;
}

function urlPath(type: RecordType, handles: string[], lang: 'en' | 'hi'): string {
  const base = type === 'product' ? '/product/' : type === 'collection' ? '/collections/' : '/shop/';
  return `${lang === 'hi' ? '/hi' : ''}${base}${handles.join('/')}`;
}

function parse(body: unknown, rec: NonNullable<ReturnType<typeof recordOf>>, lang: 'en' | 'hi'): ResolveResult {
  const row = Array.isArray(body) ? body[0] : body;
  if (!row || typeof row !== 'object') return { kind: 'none' };
  const r = row as { result?: unknown; handle?: unknown; path?: unknown };
  const handles = (): string[] | null => {
    if (rec.type === 'category') {
      const p = Array.isArray(r.path) ? r.path : typeof r.path === 'string' ? r.path.split('/') : null;
      const list = p?.filter((s): s is string => typeof s === 'string' && s !== '') ?? [];
      return list.length > 0 ? list : null;
    }
    return typeof r.handle === 'string' && r.handle !== '' ? [r.handle] : null;
  };
  if (r.result === 'redirect') {
    const h = handles();
    return h ? { kind: 'redirect', path: urlPath(rec.type, h, lang) } : { kind: 'none' };
  }
  if (r.result === 'found') {
    // A category under the wrong parents answers found with its real path: send the shopper there.
    const h = rec.type === 'category' ? handles() : null;
    if (h && h.join('/') !== rec.segments.join('/')) return { kind: 'redirect', path: urlPath(rec.type, h, lang) };
    return { kind: 'published' };
  }
  return { kind: 'none' };
}

export async function resolvePath(env: WorkerEnv, path: string, doFetch?: Fetcher): Promise<ResolveResult> {
  if (!env.SUPABASE_URL) throw new ResolveError('SUPABASE_URL is not configured');
  const { lang, path: rest } = splitLang(path);
  const rec = recordOf(rest);
  if (!rec) return { kind: 'none' };
  const base = env.SUPABASE_URL.replace(/\/+$/, '');
  const f = guardedFetch(base, doFetch);
  const q = new URLSearchParams({ p_record_type: rec.type, p_handle: rec.handle });
  const url = `${base}/rest/v1/rpc/store_resolve_path?${q.toString()}`;
  const headers: Record<string, string> = { Accept: 'application/json', 'Accept-Profile': 'api' };
  if (env.SUPABASE_ANON_KEY) {
    headers.apikey = env.SUPABASE_ANON_KEY;
    headers.Authorization = `Bearer ${env.SUPABASE_ANON_KEY}`;
  }
  const res = await f(url, { method: 'GET', headers });
  if (!res.ok) throw new ResolveError(`store_resolve_path answered ${res.status}`);
  return parse(await res.json(), rec, lang);
}
