// On_Demand_Pages (design KD-5; Req 1.9, 1.10, 20.8). The router has already asked `api.store_resolve_path` and knows the
// record is published. This rewrites the public path to the internal `/_ondemand/` Astro route, which renders it with the
// same components as the build, and caches the HTML per catalog version in the Cache API.
import type { WorkerContext, WorkerEnv } from './env';
import { catalogVersion } from './live-data';
import type { Lang } from './paths';
import { guardedFetch, type Fetcher } from './resolve-path';

const CACHE_ORIGIN = 'https://ondemand-cache.invalid';
const STORE_TTL_SECONDS = 3600;
const PAGE_CACHE_CONTROL = 'public, max-age=0, must-revalidate';

export interface OnDemandDeps {
  /** Renders a request for the internal route: the Astro adapter's handler. */
  render: (request: Request, env: WorkerEnv, ctx: WorkerContext) => Promise<Response>;
  fetch?: Fetcher;
  /** The Cache API; defaults to `caches.default`. Null disables caching. */
  cache?: Cache | null;
}

/** `/product/x` becomes `/_ondemand/product/x`, and `/hi/product/x` becomes `/_ondemand/hi/product/x`. */
export function internalPath(path: string): string {
  return `/_ondemand${path}`;
}

export function onDemandCacheKey(path: string, version: string): string {
  return `${CACHE_ORIGIN}${path}?v=${encodeURIComponent(version)}`;
}

export async function handleOnDemand(
  request: Request,
  env: WorkerEnv,
  ctx: WorkerContext,
  info: { path: string; lang: Lang },
  deps: OnDemandDeps,
): Promise<Response | null> {
  const url = new URL(request.url);
  const globalCaches = (globalThis as { caches?: { default?: Cache } }).caches;
  const onWorkersDev = url.hostname.endsWith('.workers.dev');
  const cache = onWorkersDev ? null : deps.cache !== undefined ? deps.cache : (globalCaches?.default ?? null);
  const head = request.method === 'HEAD';
  const reply = (html: string, extra: Record<string, string> = {}) =>
    new Response(head ? null : html, {
      status: 200,
      headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': PAGE_CACHE_CONTROL, ...extra },
    });

  let version = 'nocache';
  if (cache && env.SUPABASE_URL) {
    version = await catalogVersion(env, guardedFetch(env.SUPABASE_URL, deps.fetch), cache, ctx);
    const hit = await cache.match(new Request(onDemandCacheKey(info.path, version)));
    if (hit) return reply(await hit.text(), { 'X-OnDemand-Cache': 'hit' });
  }

  const res = await deps.render(new Request(new URL(internalPath(info.path), url).toString(), { method: 'GET', headers: { Accept: 'text/html' } }), env, ctx);
  if (res.status === 404) return null;
  if (res.status !== 200 || !(res.headers.get('content-type') ?? '').includes('html')) {
    return new Response('Service unavailable', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'Retry-After': '30' },
    });
  }
  const html = await res.text();
  if (cache && version !== 'unknown' && version !== 'nocache') {
    ctx.waitUntil(
      cache
        .put(
          new Request(onDemandCacheKey(info.path, version)),
          new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': `max-age=${STORE_TTL_SECONDS}` } }),
        )
        .catch(() => {}),
    );
  }
  return reply(html, { 'X-OnDemand-Cache': 'miss' });
}
