// Live_Data serving (design KD-3, "Storefront_Worker and Live_Data"; Req 2.1, 2.3, 2.7).
// GET /_live/v1/products?ids=a,b&region=reg_x[&channel=sc_x][&currency=inr]
// Answers from the Cache API keyed by catalog version + Region + sorted IDs, and on a miss calls
// `api.store_live_data` (GET /rest/v1/rpc/store_live_data, profile api, anon key).
import type { WorkerContext, WorkerEnv } from './env';
import { guardedFetch, type Fetcher } from './resolve-path';

export const MAX_IDS = 60;
export const VERSION_TTL_SECONDS = 10;
const STALE_TTL_SECONDS = 3600;
const DEFAULT_MAX_AGE = 60;
const MAX_AGE_CEILING = 3600;
const ID_RE = /^[A-Za-z0-9_.:-]{1,100}$/;
const CURRENCY_RE = /^[A-Za-z]{3}$/;
const CACHE_ORIGIN = 'https://live-cache.invalid';

export interface LiveDataDeps {
  fetch?: Fetcher;
  /** The Cache API; defaults to `caches.default`. Null disables caching. */
  cache?: Cache | null;
}

export interface LiveParams {
  ids: string[];
  region: string | null;
  channel: string | null;
  currency: string | null;
}

/** Validates and normalises the query: IDs sorted and de-duplicated. Returns an error text on bad input. */
export function parseLiveParams(url: URL): LiveParams | string {
  const raw = url.searchParams.get('ids') ?? '';
  const ids = [...new Set(raw.split(',').map((s) => s.trim()).filter(Boolean))].sort();
  if (ids.length === 0) return 'ids is required';
  if (ids.length > MAX_IDS) return `ids takes at most ${MAX_IDS} products`;
  if (!ids.every((i) => ID_RE.test(i))) return 'ids holds an invalid value';
  const opt = (name: string): string | null | undefined => {
    const v = url.searchParams.get(name);
    if (v === null || v === '') return null;
    return ID_RE.test(v) ? v : undefined;
  };
  const region = opt('region');
  const channel = opt('channel');
  if (region === undefined || channel === undefined) return 'region or channel is invalid';
  const cur = url.searchParams.get('currency');
  if (cur && !CURRENCY_RE.test(cur)) return 'currency is invalid';
  return { ids, region, channel, currency: cur ? cur.toLowerCase() : null };
}

export function liveCacheKey(version: string, p: LiveParams, stale = false): string {
  const q = new URLSearchParams({
    v: stale ? '' : version, // the stale copy outlives a catalog version change
    region: p.region ?? '',
    channel: p.channel ?? '',
    currency: p.currency ?? '',
    ids: p.ids.join(','),
  });
  return `${CACHE_ORIGIN}/live/v1/products${stale ? '/stale' : ''}?${q.toString()}`;
}

function json(body: unknown, status: number, cacheControl: string, extra: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': cacheControl, ...extra },
  });
}

function fail(status: number, message: string): Response {
  return json({ error: message }, status, 'no-store');
}

function supabaseHeaders(env: WorkerEnv): Record<string, string> {
  const h: Record<string, string> = { Accept: 'application/json', 'Accept-Profile': 'api' };
  if (env.SUPABASE_ANON_KEY) {
    h.apikey = env.SUPABASE_ANON_KEY;
    h.Authorization = `Bearer ${env.SUPABASE_ANON_KEY}`;
  }
  return h;
}

/** Catalog version string from the Cache API (refreshed at most every 10 s) or `api.store_catalog_versions`. */
export async function catalogVersion(env: WorkerEnv, f: Fetcher, cache: Cache | null, ctx: WorkerContext): Promise<string> {
  const key = new Request(`${CACHE_ORIGIN}/catalog-version`);
  const hit = cache ? await cache.match(key) : undefined;
  if (hit) return hit.text();
  const base = (env.SUPABASE_URL ?? '').replace(/\/+$/, '');
  try {
    const res = await f(`${base}/rest/v1/rpc/store_catalog_versions`, { method: 'GET', headers: supabaseHeaders(env) });
    if (!res.ok) return 'unknown';
    const body = (await res.json()) as { versions?: Record<string, unknown> };
    const versions = body?.versions;
    if (!versions || typeof versions !== 'object') return 'unknown';
    const version = Object.keys(versions)
      .sort()
      .map((k) => `${k}=${String(versions[k])}`)
      .join(';') || 'none';
    if (cache) {
      ctx.waitUntil(
        cache
          .put(key, new Response(version, { headers: { 'Cache-Control': `max-age=${VERSION_TTL_SECONDS}` } }))
          .catch(() => {}),
      );
    }
    return version;
  } catch {
    return 'unknown';
  }
}

function maxAgeOf(body: { max_age_seconds?: unknown }, res: Response): number {
  const m = /max-age=(\d+)/.exec(res.headers.get('cache-control') ?? '');
  const n = m ? Number(m[1]) : typeof body.max_age_seconds === 'number' ? body.max_age_seconds : DEFAULT_MAX_AGE;
  return Number.isFinite(n) && n >= 0 ? Math.min(Math.floor(n), MAX_AGE_CEILING) : DEFAULT_MAX_AGE;
}

function isLiveData(body: unknown): body is { products: unknown[]; max_age_seconds?: unknown } {
  return !!body && typeof body === 'object' && Array.isArray((body as { products?: unknown }).products);
}

async function fetchLive(env: WorkerEnv, f: Fetcher, p: LiveParams): Promise<{ body: { max_age_seconds?: unknown }; maxAge: number }> {
  const base = (env.SUPABASE_URL ?? '').replace(/\/+$/, '');
  const q = new URLSearchParams();
  q.set('p_product_ids', `{${p.ids.map((i) => `"${i}"`).join(',')}}`);
  if (p.channel) q.set('p_sales_channel_id', p.channel);
  if (p.region) q.set('p_region_id', p.region);
  if (p.currency) q.set('p_currency_code', p.currency);
  const res = await f(`${base}/rest/v1/rpc/store_live_data?${q.toString()}`, { method: 'GET', headers: supabaseHeaders(env) });
  if (!res.ok) throw new Error(`store_live_data answered ${res.status}`);
  const body = await res.json();
  if (!isLiveData(body)) throw new Error('store_live_data answered no products');
  return { body, maxAge: maxAgeOf(body, res) };
}

function reply(request: Request, body: string, cacheControl: string, extra: Record<string, string> = {}): Response {
  return new Response(request.method === 'HEAD' ? null : body, {
    status: 200,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': cacheControl, ...extra },
  });
}

export async function handleLiveData(
  request: Request,
  env: WorkerEnv,
  ctx: WorkerContext,
  deps: LiveDataDeps = {},
): Promise<Response> {
  if (!env.SUPABASE_URL) return fail(503, 'Live data is not configured');
  const url = new URL(request.url);
  const params = parseLiveParams(url);
  if (typeof params === 'string') return fail(400, params);

  const f = guardedFetch(env.SUPABASE_URL, deps.fetch);
  const signedIn = request.headers.has('Authorization');
  const onWorkersDev = url.hostname.endsWith('.workers.dev');
  const globalCaches = (globalThis as { caches?: { default?: Cache } }).caches;
  const cache = signedIn || onWorkersDev ? null : deps.cache !== undefined ? deps.cache : (globalCaches?.default ?? null);

  const version = cache ? await catalogVersion(env, f, cache, ctx) : 'nocache';
  const key = new Request(liveCacheKey(version, params));
  const hit = cache ? await cache.match(key) : undefined;
  if (hit) return reply(request, await hit.text(), hit.headers.get('cache-control') ?? 'no-store', { 'X-Live-Cache': 'hit' });

  try {
    const { body, maxAge } = await fetchLive(env, f, params);
    const text = JSON.stringify(body);
    const cc = signedIn || maxAge === 0 ? 'no-store' : `public, max-age=${maxAge}, s-maxage=${maxAge}`;
    if (cache && cc !== 'no-store') {
      const headers = { 'Content-Type': 'application/json; charset=utf-8' };
      ctx.waitUntil(
        Promise.all([
          cache.put(key, new Response(text, { headers: { ...headers, 'Cache-Control': cc } })),
          cache.put(
            new Request(liveCacheKey(version, params, true)),
            new Response(text, { headers: { ...headers, 'Cache-Control': `max-age=${STALE_TTL_SECONDS}` } }),
          ),
        ]).catch(() => {}),
      );
    }
    return reply(request, text, cc, { 'X-Live-Cache': 'miss' });
  } catch {
    // Backend error: answer with the last known answer for the same IDs, marked stale (the client applies Req 2.4).
    const old = cache ? await cache.match(new Request(liveCacheKey(version, params, true))) : undefined;
    if (old) return reply(request, await old.text(), 'no-store', { 'X-Live-Cache': 'stale' });
    return fail(502, 'Live data is not available');
  }
}
