// Storefront_Worker entry (design KD-5). The router in src/worker/ answers every request that no
// static asset answers; the Astro Cloudflare adapter's handler stays wired in for the prerender
// endpoints that `astro build` calls.
import astro from '@astrojs/cloudflare/entrypoints/server';
import type { WorkerContext, WorkerEnv } from './worker/env';
import { handleOnDemand } from './worker/ondemand';
import { handlePreview } from './worker/preview';
import { handleRequest } from './worker/router';

type AstroFetch = (request: Request, env: WorkerEnv, ctx: WorkerContext) => Promise<Response>;
const delegate = astro.fetch as unknown as AstroFetch;

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerContext): Promise<Response> {
    return handleRequest(request, env, ctx, {
      delegate,
      onDemand: (req, e, c, info) => handleOnDemand(req, e, c, info, { render: delegate }),
      preview: (req, e, c, info) => handlePreview(req, e, c, info),
    });
  },
};
