// Security and cache headers for every Worker response (Req 21.1, 21.2; design KD-14).
import { buildCsp, staticSecurityHeaders } from '../../scripts/security-headers.mjs';
import type { WorkerEnv } from './env';

export interface CspData {
  scriptHashes: string[];
  mediaOrigin?: string | null;
  /** Hosts of the Marketing_Tags configured at build time. */
  marketingOrigins?: string[];
}

let cached: CspData | undefined;

/** Reads the hashes that the build wrote to `/_csp.json`; an unreadable file gives a policy with no inline hashes. */
export async function loadCspData(env: WorkerEnv): Promise<CspData> {
  if (cached) return cached;
  try {
    const res = await env.ASSETS.fetch('https://assets.invalid/_csp.json');
    if (res.ok && (res.headers.get('content-type') ?? '').includes('json')) {
      const data = (await res.json()) as Partial<CspData>;
      if (Array.isArray(data.scriptHashes)) {
        cached = { scriptHashes: data.scriptHashes.filter((h) => typeof h === 'string'), mediaOrigin: data.mediaOrigin,
          marketingOrigins: Array.isArray(data.marketingOrigins) ? data.marketingOrigins.filter((h) => typeof h === 'string') : [],
        };
        return cached;
      }
    }
  } catch {
    // fall through to the empty set
  }
  return { scriptHashes: [] };
}

export function resetCspCache(): void {
  cached = undefined;
}

export function cspFor(env: WorkerEnv, data: CspData): string {
  return buildCsp({
    scriptHashes: data.scriptHashes,
    supabaseUrl: env.SUPABASE_URL,
    mediaOrigin: env.MEDIA_ORIGIN ?? data.mediaOrigin ?? undefined,
    marketingOrigins: data.marketingOrigins,
  });
}

const HTML_CACHE = 'public, max-age=0, must-revalidate';
const IMMUTABLE = 'public, max-age=31536000, immutable';

/** Returns a copy of the response with the security headers, and a Cache-Control when it has none. */
export function withHeaders(response: Response, env: WorkerEnv, data: CspData, pathname: string): Response {
  const out = new Response(response.body, response);
  for (const [name, value] of Object.entries(staticSecurityHeaders())) out.headers.set(name, value);
  out.headers.set('Content-Security-Policy', cspFor(env, data));
  if (!out.headers.has('Cache-Control')) {
    out.headers.set('Cache-Control', pathname.startsWith('/_astro/') ? IMMUTABLE : HTML_CACHE);
  }
  return out;
}
