// `/_preview/<path>?token=…` (design "Storefront_Worker and Live_Data", Req 6.3): shows the draft layout or an unpublished
// product that `api.store_preview` returns for a valid 10-minute token. Every response is `private, no-store` and `noindex`,
// and nothing here is written to a cache. The page lists what the shopper-facing pages would use, from the same data.
import type { WorkerContext, WorkerEnv } from './env';
import type { Lang } from './paths';
import { guardedFetch, type Fetcher } from './resolve-path';

const PREVIEW_HEADERS = {
  'Cache-Control': 'private, no-store',
  'X-Robots-Tag': 'noindex, nofollow',
  'Content-Type': 'text/html; charset=utf-8',
  'Referrer-Policy': 'no-referrer',
} as const;

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);

export function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function page(status: number, lang: Lang, title: string, body: string, head: Request['method']): Response {
  const html =
    `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="robots" content="noindex, nofollow">` +
    `<meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)}</title></head>` +
    `<body><main><p>${lang === 'hi' ? 'पूर्वावलोकन' : 'Preview'}</p>${body}</main></body></html>`;
  return new Response(head === 'HEAD' ? null : html, { status, headers: PREVIEW_HEADERS });
}

const list = (items: unknown[]): string => (items.length ? `<ul>${items.map((i) => `<li>${i}</li>`).join('')}</ul>` : '<p>None</p>');
const keys = (v: unknown): string[] => (Array.isArray(v) ? v.filter((k): k is string => typeof k === 'string') : []);

/** The preview body for a draft home page, a draft product page or an unpublished product. Everything is escaped. */
export function renderPreview(data: Obj, path: string): string | null {
  const layout = isObj(data.layout) ? data.layout : {};
  const product = isObj(data.product) ? data.product : null;
  const sections = Array.isArray(layout.sections) ? layout.sections.filter(isObj) : [];
  const onHome = path === '/home';
  const onProduct = path.startsWith('/product/');
  if (!onHome && !onProduct) return null;
  if (onProduct && !product) return null;
  const h = (s: unknown) => escapeHtml(typeof s === 'string' ? s : '');
  const parts: string[] = [];
  if (onProduct && product) {
    parts.push(`<h1>${h(product.title)}</h1><p>${h(product.handle)} · ${h(product.status)}</p>`);
    parts.push(`<h2>PDP_Blocks</h2>${list(keys(layout.pdp_blocks).map(h))}`);
  } else {
    parts.push('<h1>Home page</h1>');
    parts.push(
      `<h2>Sections</h2>${list(sections.map((s) => `${h(s.type)}${s.hidden === true ? ' (hidden)' : ''}${s.id ? ` · ${h(s.id)}` : ''}`))}`,
    );
  }
  parts.push(`<h2>Filters</h2>${list(keys(layout.plp_filters).map(h))}`);
  parts.push(`<h2>Badges</h2>${list(keys(layout.badges).map(h))}`);
  return parts.join('');
}

export async function handlePreview(
  request: Request,
  env: WorkerEnv,
  _ctx: WorkerContext,
  info: { path: string; lang: Lang },
  doFetch?: Fetcher,
): Promise<Response> {
  const method = request.method;
  const token = new URL(request.url).searchParams.get('token') ?? '';
  const denied = () => page(403, info.lang, 'Preview unavailable', '<h1>This preview link is invalid or has expired.</h1>', method);
  if (!token || token.length > 1024 || !env.SUPABASE_URL) return denied();
  const base = env.SUPABASE_URL.replace(/\/+$/, '');
  const f = guardedFetch(base, doFetch);
  const headers: Record<string, string> = { Accept: 'application/json', 'Accept-Profile': 'api' };
  if (env.SUPABASE_ANON_KEY) {
    headers.apikey = env.SUPABASE_ANON_KEY;
    headers.Authorization = `Bearer ${env.SUPABASE_ANON_KEY}`;
  }
  let res: Response;
  try {
    res = await f(`${base}/rest/v1/rpc/store_preview?${new URLSearchParams({ p_token: token }).toString()}`, { method: 'GET', headers, cache: 'no-store' });
  } catch {
    return page(503, info.lang, 'Preview unavailable', '<h1>The preview could not be loaded. Try again.</h1>', method);
  }
  if (res.status === 403 || res.status === 401) return denied();
  if (!res.ok) return page(503, info.lang, 'Preview unavailable', '<h1>The preview could not be loaded. Try again.</h1>', method);
  const data: unknown = await res.json().catch(() => null);
  if (!isObj(data) || isObj(data.error)) return denied();
  const body = renderPreview(data, info.path);
  if (body === null) return page(404, info.lang, 'Not found', '<h1>There is nothing to preview at this path.</h1>', method);
  return page(200, info.lang, 'Preview', body, method);
}
