// One source of truth for the security headers (design KD-14; Req 21.1, 21.2).
// Used by the build (scripts/generate-headers.mjs, for `_headers`) and by the Storefront_Worker.
// Plain JS so Node can import it without a TypeScript step.

export const TURNSTILE_ORIGIN = 'https://challenges.cloudflare.com';
export const RAZORPAY_SCRIPT_ORIGIN = 'https://checkout.razorpay.com';
export const RAZORPAY_API_ORIGIN = 'https://api.razorpay.com';
export const RAZORPAY_FRAME_ORIGINS = ['https://api.razorpay.com', 'https://checkout.razorpay.com'];
export const CLOUDINARY_ORIGIN = 'https://res.cloudinary.com';

export const HSTS = 'max-age=63072000; includeSubDomains';

/** Origin of a URL, or undefined when it is empty or not a valid http(s) URL. */
export function originOf(value) {
  if (!value) return undefined;
  try {
    const u = new URL(value);
    return u.protocol === 'https:' || u.protocol === 'http:' ? u.origin : undefined;
  } catch {
    return undefined;
  }
}

const uniq = (list) => [...new Set(list.filter(Boolean))];

const GOOGLE_ORIGINS = [
  'https://www.googletagmanager.com',
  'https://www.google-analytics.com',
  'https://*.google-analytics.com',
  'https://*.analytics.google.com',
  'https://www.googleadservices.com',
  'https://googleads.g.doubleclick.net',
  'https://www.google.com',
];
const META_ORIGINS = ['https://connect.facebook.net', 'https://www.facebook.com'];

/**
 * Hosts of the configured Marketing_Tags (Req 21.1). A tag with no ID in the environment adds no host.
 * @param {Record<string, string | undefined>} [env] PUBLIC_GA4_ID, PUBLIC_GOOGLE_ADS_ID, PUBLIC_META_PIXEL_ID
 */
export function marketingOriginsFor(env = {}) {
  const google = Boolean((env.PUBLIC_GA4_ID ?? '').trim() || (env.PUBLIC_GOOGLE_ADS_ID ?? '').trim());
  const meta = Boolean((env.PUBLIC_META_PIXEL_ID ?? '').trim());
  return [...(google ? GOOGLE_ORIGINS : []), ...(meta ? META_ORIGINS : [])];
}

/**
 * Build the Content-Security-Policy.
 * @param {{ scriptHashes?: string[], supabaseUrl?: string, mediaOrigin?: string, marketingOrigins?: string[] }} [opts]
 *   scriptHashes: values like `sha256-...` (without quotes).
 */
export function buildCsp(opts = {}) {
  const { scriptHashes = [], supabaseUrl, mediaOrigin, marketingOrigins = [] } = opts;
  const supabase = originOf(supabaseUrl);
  const media = originOf(mediaOrigin);
  const hashes = scriptHashes.map((h) => `'${h.replace(/^'|'$/g, '')}'`);
  const directives = {
    'default-src': ["'self'"],
    'script-src': uniq(["'self'", ...hashes, TURNSTILE_ORIGIN, RAZORPAY_SCRIPT_ORIGIN, ...marketingOrigins]),
    'style-src': ["'self'"],
    'img-src': uniq(["'self'", 'data:', media, supabase, CLOUDINARY_ORIGIN, ...marketingOrigins]),
    'connect-src': uniq(["'self'", supabase, RAZORPAY_API_ORIGIN, ...marketingOrigins]),
    'frame-src': [TURNSTILE_ORIGIN, ...RAZORPAY_FRAME_ORIGINS],
    'frame-ancestors': ["'none'"],
    'object-src': ["'none'"],
    'base-uri': ["'none'"],
  };
  return Object.entries(directives)
    .map(([name, values]) => `${name} ${values.join(' ')}`)
    .join('; ');
}

/** Every security header except the CSP value, which depends on the build's hashes. */
export function staticSecurityHeaders() {
  return {
    'Strict-Transport-Security': HSTS,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  };
}

/** All security headers as a record, with the CSP. */
export function securityHeaders(opts = {}) {
  return { 'Content-Security-Policy': buildCsp(opts), ...staticSecurityHeaders() };
}
