// Storefront_Worker routing (design "Storefront_Worker and Live_Data"; Req 1.10, 21.7).
// Static assets answer first (Workers static assets); this runs for every other request.
import type { WorkerContext, WorkerEnv } from './env';
import { loadCspData, withHeaders, type CspData } from './headers';
import { handleLiveData } from './live-data';
import { canonicalPath, routeOf, type Lang } from './paths';
import { resolvePath, type ResolveResult, type Fetcher } from './resolve-path';

type Handler = (request: Request, env: WorkerEnv, ctx: WorkerContext) => Promise<Response>;

export interface RouterDeps {
  /** The Astro adapter's handler; serves the prerender endpoints at build time. */
  delegate?: Handler;
  liveData?: Handler;
  /** Renders an On_Demand_Page for a published catalog path; a later task provides it. */
  onDemand?: (request: Request, env: WorkerEnv, ctx: WorkerContext, info: { path: string; lang: Lang }) => Promise<Response | null>;
  /** Renders a preview; a later task provides it. */
  preview?: (request: Request, env: WorkerEnv, ctx: WorkerContext, info: { path: string; lang: Lang }) => Promise<Response | null>;
  fetch?: Fetcher;
  loadCsp?: (env: WorkerEnv) => Promise<CspData>;
}

const PRERENDER_PATHS = new Set(['/__astro_static_paths', '/__astro_prerender', '/__astro_static_images']);
const REDIRECT_CACHE = 'public, max-age=300';

const NOT_FOUND_FALLBACK =
  '<!doctype html><html lang="en"><meta charset="utf-8"><title>Not found</title><h1>Page not found</h1>';

function redirect(location: string): Response {
  return new Response(null, { status: 301, headers: { Location: location, 'Cache-Control': REDIRECT_CACHE } });
}

async function notFound(request: Request, env: WorkerEnv): Promise<Response> {
  let body: BodyInit = NOT_FOUND_FALLBACK;
  let type = 'text/html; charset=utf-8';
  try {
    const res = await env.ASSETS.fetch(new URL('/404', request.url).toString());
    if (res.ok && (res.headers.get('content-type') ?? '').includes('html')) {
      body = await res.text();
      type = res.headers.get('content-type') ?? type;
    }
  } catch {
    // keep the inline page
  }
  return new Response(request.method === 'HEAD' ? null : body, {
    status: 404,
    headers: { 'Content-Type': type, 'Cache-Control': 'public, max-age=0, must-revalidate' },
  });
}

async function route(request: Request, env: WorkerEnv, ctx: WorkerContext, deps: RouterDeps): Promise<Response> {
  const url = new URL(request.url);

  if (PRERENDER_PATHS.has(url.pathname) && deps.delegate) {
    const res = await deps.delegate(request, env, ctx);
    // Prerendering the site's own 404 page (src/pages/404.astro) returns its HTML with status 404; keep that body so the
    // build writes it to 404.html (Req 20.9). Any other 404 gets the fallback page.
    const isHtml = (res.headers.get('content-type') ?? '').includes('html');
    return res.status === 404 && !isHtml ? notFound(request, env) : res;
  }

  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('Method not allowed', {
      status: 405,
      headers: { Allow: 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' },
    });
  }

  const canonical = canonicalPath(url.pathname);
  if (canonical !== url.pathname) return redirect(`${canonical}${url.search}`);

  const r = routeOf(canonical);
  switch (r.kind) {
    case 'live':
      return (deps.liveData ?? handleLiveData)(request, env, ctx);
    case 'preview': {
      const res = deps.preview ? await deps.preview(request, env, ctx, { path: r.path, lang: r.lang }) : null;
      return res ?? notFound(request, env);
    }
    case 'catalog': {
      let result: ResolveResult;
      try {
        result = await resolvePath(env, canonical, deps.fetch);
      } catch {
        return new Response('Service unavailable', {
          status: 503,
          headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'Retry-After': '30' },
        });
      }
      if (result.kind === 'redirect') return redirect(`${result.path}${url.search}`);
      if (result.kind === 'published' && deps.onDemand) {
        const res = await deps.onDemand(request, env, ctx, { path: canonical, lang: r.lang });
        if (res) return res;
      }
      return notFound(request, env);
    }
    default:
      return notFound(request, env);
  }
}

/** Handles one request and adds the security headers to the response. */
export async function handleRequest(
  request: Request,
  env: WorkerEnv,
  ctx: WorkerContext,
  deps: RouterDeps = {},
): Promise<Response> {
  const response = await route(request, env, ctx, deps);
  const data = await (deps.loadCsp ?? loadCspData)(env);
  return withHeaders(response, env, data, new URL(request.url).pathname);
}
